aditof::Status Adsd3500Sensor::start() {
    using namespace aditof;
    Status status = Status::OK;
    struct VideoDev *dev;
    struct v4l2_buffer buf;

    LOG(INFO) << "Adsd3500Sensor::start enter"
              << ", numVideoDevs=" << m_implData->numVideoDevs
              << ", capturesPerFrame=" << m_capturesPerFrame;

    for (unsigned int i = 0; i < m_implData->numVideoDevs; i++) {
        dev = &m_implData->videoDevs[i];
        LOG(INFO) << "start: device state"
                  << ", device=" << i
                  << ", fd=" << dev->fd
                  << ", sfd=" << dev->sfd
                  << ", started=" << dev->started
                  << ", videoBuffers=" << static_cast<void *>(dev->videoBuffers)
                  << ", nVideoBuffers=" << dev->nVideoBuffers
                  << ", videoBuffersType=" << dev->videoBuffersType
                  << ", planes=" << static_cast<void *>(dev->planes);

        if (dev->started) {
            LOG(INFO) << "Device already started";
            return Status::BUSY;
        }
        LOG(INFO) << "Starting device " << i;

        for (unsigned int bufferIndex = 0; bufferIndex < dev->nVideoBuffers;
             bufferIndex++) {
            CLEAR(buf);
            buf.type = dev->videoBuffersType;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = bufferIndex;
            buf.m.planes = dev->planes;
            buf.length = 1;

            LOG(INFO) << "start: VIDIOC_QBUF begin"
                      << ", device=" << i
                      << ", bufferIndex=" << bufferIndex
                      << ", type=" << buf.type
                      << ", memory=" << buf.memory
                      << ", length=" << buf.length
                      << ", planes=" << static_cast<void *>(buf.m.planes);

            if (xioctl(dev->fd, VIDIOC_QBUF, &buf) == -1) {
                LOG(WARNING)
                    << "VIDIOC_QBUF error during start "
                    << ", device=" << i << ", bufferIndex=" << bufferIndex
                    << "errno: " << errno << " error: " << strerror(errno);
                return Status::GENERIC_ERROR;
            }

            LOG(INFO) << "start: VIDIOC_QBUF done"
                      << ", device=" << i
                      << ", bufferIndex=" << bufferIndex
                      << ", bytesused=" << buf.bytesused
                      << ", flags=" << buf.flags
                      << ", sequence=" << buf.sequence;
        }

        LOG(INFO) << "start: VIDIOC_STREAMON begin"
                  << ", device=" << i
                  << ", fd=" << dev->fd
                  << ", type=" << dev->videoBuffersType;
        if (xioctl(dev->fd, VIDIOC_STREAMON, &dev->videoBuffersType) != 0) {
            LOG(WARNING) << "VIDIOC_STREAMON error "
                         << "errno: " << errno << " error: " << strerror(errno);
            return Status::GENERIC_ERROR;
        }
        LOG(INFO) << "start: VIDIOC_STREAMON done"
                  << ", device=" << i
                  << ", type=" << dev->videoBuffersType;

        dev->started = true;
        LOG(INFO) << "start: device marked started"
                  << ", device=" << i;
    }

    LOG(INFO) << "Adsd3500Sensor::start done";
    return status;
}

