Adsd3500Sensor::setFrameType(const aditof::DepthSensorFrameType &type) {

    using namespace aditof;
    Status status = Status::OK;
    struct VideoDev *dev;

    LOG(INFO) << "setFrameType: enter"
              << ", requested type=" << type.type
              << ", width=" << type.width
              << ", height=" << type.height
              << ", current type=" << m_implData->frameType.type
              << ", hostConnectionType="
              << static_cast<int>(m_hostConnectionType)
              << ", numVideoDevs=" << m_implData->numVideoDevs;

    for (unsigned int i = 0; i < m_implData->numVideoDevs; i++) {
        dev = &m_implData->videoDevs[i];
        LOG(INFO) << "setFrameType: pre-stop check"
                  << ", device=" << i
                  << ", fd=" << dev->fd
                  << ", sfd=" << dev->sfd
                  << ", started=" << dev->started
                  << ", videoBuffers=" << static_cast<void *>(dev->videoBuffers)
                  << ", nVideoBuffers=" << dev->nVideoBuffers;
        if (dev->started) {
            stop();
        }
    }

    bool reopenSensor = false;

    for (unsigned int i = 0; i < m_implData->numVideoDevs; i++) {
        dev = &m_implData->videoDevs[i];
        const bool hasMappedBuffers =
            dev->videoBuffers != nullptr || dev->nVideoBuffers != 0;
        const bool hasInvalidFds = dev->fd == -1 || dev->sfd == -1;

        if (!dev->started && !hasMappedBuffers && !hasInvalidFds) {
            LOG(INFO) << "setFrameType: reuse open device without close/reopen"
                      << ", device=" << i
                      << ", fd=" << dev->fd
                      << ", sfd=" << dev->sfd
                      << ", started=" << dev->started
                      << ", videoBuffers="
                      << static_cast<void *>(dev->videoBuffers)
                      << ", nVideoBuffers=" << dev->nVideoBuffers;
            continue;
        }

        reopenSensor = true;

        LOG(INFO) << "setFrameType: release/open reset begin"
                  << ", device=" << i
                  << ", fd=" << dev->fd
                  << ", sfd=" << dev->sfd
                  << ", videoBuffers=" << static_cast<void *>(dev->videoBuffers)
                  << ", nVideoBuffers=" << dev->nVideoBuffers;

        for (unsigned int bufferIndex = 0; bufferIndex < dev->nVideoBuffers;
             bufferIndex++) {
            LOG(INFO) << "setFrameType: initial munmap begin"
                      << ", device=" << i
                      << ", bufferIndex=" << bufferIndex
                      << ", start="
                      << static_cast<void *>(dev->videoBuffers[bufferIndex].start)
                      << ", length=" << dev->videoBuffers[bufferIndex].length;
            if (munmap(dev->videoBuffers[bufferIndex].start,
                       dev->videoBuffers[bufferIndex].length) == -1) {
                LOG(WARNING)
                    << "munmap error "
                    << "errno: " << errno << " error: " << strerror(errno);
            }
            LOG(INFO) << "setFrameType: initial munmap done"
                      << ", device=" << i
                      << ", bufferIndex=" << bufferIndex;
        }
        free(dev->videoBuffers);
        dev->videoBuffers = nullptr;
        dev->nVideoBuffers = 0;

