                LOG(INFO) << "setFrameType: VIDIOC_REQBUFS release begin"
                          << ", device=" << i
                          << ", type=" << req.type
                          << ", count=" << req.count;
                if (xioctl(dev->fd, VIDIOC_REQBUFS, &req) == -1) {
                    LOG(WARNING)
                        << "VIDIOC_REQBUFS error "
                        << "errno: " << errno << " error: " << strerror(errno);
                    return Status::GENERIC_ERROR;
                }
                LOG(INFO) << "setFrameType: VIDIOC_REQBUFS release done"
                          << ", device=" << i
                          << ", returned count=" << req.count;
            } else if (dev->nVideoBuffers) {
                LOG(INFO) << "setFrameType: unchanged type with existing buffers"
                          << ", device=" << i
                          << ", nVideoBuffers=" << dev->nVideoBuffers;
                return status;
            }

            __u32 pixelFormat = 0;

            if (m_implData->imagerType == ImagerType::IMAGER_ADSD3100) {
                if (type.type == "lr-qnative" || type.type == "sr-qnative" ||
                    type.type == "lr-mixed" || type.type == "sr-mixed" ||
                    type.type == "qmp") {
                    pixelFormat = V4L2_PIX_FMT_SBGGR8;
                } else if (type.type == "lr-native" ||
                           type.type == "sr-native" || type.type == "mp") {
                    if (m_controls["abBits"] == "6") {
                        pixelFormat = V4L2_PIX_FMT_SBGGR8;
                    } else {
                        pixelFormat = V4L2_PIX_FMT_SBGGR12;
                    }
                } else if (type.type == "pcm-native") {
                    pixelFormat = V4L2_PIX_FMT_SBGGR12;
                } else {
                    LOG(ERROR) << "frame type: " << type.type << " "
                               << "is unhandled";
                    return Status::GENERIC_ERROR;
                }
            } else if (m_implData->imagerType == ImagerType::IMAGER_ADSD3030) {
                if (type.type == "sr-native" || type.type == "lr-native" ||
                    type.type == "sr-qnative" || type.type == "lr-qnative" ||
                    type.type == "vga" || type.type == "sr-mixed" ||
                    type.type == "lr-mixed") {
#ifdef NXP
                    pixelFormat =
                        V4L2_PIX_FMT_SBGGR8; // TO DO: Add implementation to automatically find pixel format based on resolution instead of all this harcoding
#else
                    pixelFormat = V4L2_PIX_FMT_SRGGB8;
#endif
                } else if (type.type == "pcm-native") {
                    pixelFormat = V4L2_PIX_FMT_SBGGR12;
                } else {
                    LOG(ERROR) << "frame type: " << type.type << " "
                               << "is unhandled";
                    return Status::GENERIC_ERROR;
                }
            } else {
                LOG(ERROR) << "Unknow imager type!";
            }

            /* Set the frame format in the driver */
            CLEAR(fmt);
            fmt.type = dev->videoBuffersType;
            fmt.fmt.pix.pixelformat = pixelFormat;
            fmt.fmt.pix.width = type.width;
            fmt.fmt.pix.height = type.height;

            //TO DO: remove hardcoded 16bit ab resolutions
            if (m_implData->imagerType == ImagerType::IMAGER_ADSD3100 &&
                m_controls["abBits"] == "6") {
                if (type.type == "lr-native" || type.type == "mp") {
                    fmt.fmt.pix.width = 2048;
                    fmt.fmt.pix.height = 3328;

                } else if (type.type == "sr-native") {
                    fmt.fmt.pix.width = 2048;
                    fmt.fmt.pix.height = 2560;
                }
            }

            LOG(INFO) << "setFrameType: VIDIOC_S_FMT begin"
                      << ", device=" << i
                      << ", fd=" << dev->fd
                      << ", type=" << fmt.type
                      << ", pixelformat=" << fmt.fmt.pix.pixelformat
                      << ", width=" << fmt.fmt.pix.width
                      << ", height=" << fmt.fmt.pix.height;
            if (xioctl(dev->fd, VIDIOC_S_FMT, &fmt) == -1) {
                LOG(WARNING) << "Setting Pixel Format error, errno: " << errno
                             << " error: " << strerror(errno);
                return Status::GENERIC_ERROR;
            }
            LOG(INFO) << "setFrameType: VIDIOC_S_FMT done"
                      << ", device=" << i
                      << ", returned width=" << fmt.fmt.pix.width
                      << ", returned height=" << fmt.fmt.pix.height
                      << ", bytesperline=" << fmt.fmt.pix.bytesperline
                      << ", sizeimage=" << fmt.fmt.pix.sizeimage;

            /* Allocate the video buffers in the driver */
            CLEAR(req);
            req.count = m_capturesPerFrame + EXTRA_BUFFERS_COUNT;
            req.type = dev->videoBuffersType;
            req.memory = V4L2_MEMORY_MMAP;

            LOG(INFO) << "setFrameType: VIDIOC_REQBUFS allocate begin"
                      << ", device=" << i
                      << ", requested count=" << req.count
                      << ", type=" << req.type
                      << ", memory=" << req.memory;
            if (xioctl(dev->fd, VIDIOC_REQBUFS, &req) == -1) {
                LOG(WARNING)
                    << "VIDIOC_REQBUFS error "
                    << "errno: " << errno << " error: " << strerror(errno);
                return Status::GENERIC_ERROR;
            }
            LOG(INFO) << "setFrameType: VIDIOC_REQBUFS allocate done"
                      << ", device=" << i
                      << ", returned count=" << req.count;

            dev->videoBuffers =
                (buffer *)calloc(req.count, sizeof(*dev->videoBuffers));
            if (!dev->videoBuffers) {
                LOG(WARNING)
                    << "Failed to allocate video m_implData->videoBuffers";
                return Status::GENERIC_ERROR;
            }
            LOG(INFO) << "setFrameType: calloc video buffers done"
                      << ", device=" << i
                      << ", videoBuffers="
                      << static_cast<void *>(dev->videoBuffers)
                      << ", count=" << req.count;

            for (dev->nVideoBuffers = 0; dev->nVideoBuffers < req.count;
                 dev->nVideoBuffers++) {
                CLEAR(buf);
                buf.type = dev->videoBuffersType;
                buf.memory = V4L2_MEMORY_MMAP;
                buf.index = dev->nVideoBuffers;
                buf.m.planes = dev->planes;
                buf.length = 1;

                LOG(INFO) << "setFrameType: VIDIOC_QUERYBUF begin"
                          << ", device=" << i
                          << ", bufferIndex=" << dev->nVideoBuffers
                          << ", type=" << buf.type
                          << ", memory=" << buf.memory
                          << ", planes=" << static_cast<void *>(buf.m.planes);
                if (xioctl(dev->fd, VIDIOC_QUERYBUF, &buf) == -1) {
                    LOG(WARNING)
                        << "VIDIOC_QUERYBUF error "
                        << "errno: " << errno << " error: " << strerror(errno);
                    return Status::GENERIC_ERROR;
                }
                LOG(INFO) << "setFrameType: VIDIOC_QUERYBUF done"
                          << ", device=" << i
                          << ", bufferIndex=" << dev->nVideoBuffers
                          << ", bytesused=" << buf.bytesused
                          << ", length=" << buf.length
                          << ", flags=" << buf.flags;

                if (dev->videoBuffersType == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
                    length = buf.length;
                    offset = buf.m.offset;
                } else {
                    length = buf.m.planes[0].length;
                    offset = buf.m.planes[0].m.mem_offset;
                }

                LOG(INFO) << "setFrameType: mmap begin"
                          << ", device=" << i
                          << ", bufferIndex=" << dev->nVideoBuffers
                          << ", length=" << length
                          << ", offset=" << offset
                          << ", fd=" << dev->fd;
                dev->videoBuffers[dev->nVideoBuffers].start =
                    mmap(NULL, length, PROT_READ | PROT_WRITE, MAP_SHARED,
                         dev->fd, offset);

                if (dev->videoBuffers[dev->nVideoBuffers].start == MAP_FAILED) {
                    LOG(WARNING)
                        << "mmap error "
                        << "errno: " << errno << " error: " << strerror(errno);
                    return Status::GENERIC_ERROR;
                }

                dev->videoBuffers[dev->nVideoBuffers].length = length;
                LOG(INFO) << "setFrameType: mmap done"
                          << ", device=" << i
                          << ", bufferIndex=" << dev->nVideoBuffers
                          << ", start="
                          << static_cast<void *>(
                                 dev->videoBuffers[dev->nVideoBuffers].start)
                          << ", length="
                          << dev->videoBuffers[dev->nVideoBuffers].length;
            }
            LOG(INFO) << "setFrameType: device buffer setup done"
                      << ", device=" << i
                      << ", nVideoBuffers=" << dev->nVideoBuffers;
        }
    }

    m_implData->frameType = type;
    LOG(INFO) << "setFrameType: done"
              << ", active type=" << m_implData->frameType.type;

    return status;
}

